/* Toolbox 2.8.2 — password-encrypted offline backups. Existing browser document storage is NOT yet encrypted. */
(()=>{'use strict';
const MAX_FILE=60*1024*1024, MAX_ATTACHMENT=15*1024*1024;
const enc=new TextEncoder(),dec=new TextDecoder(),ITERATIONS=310000;
const bytesTo64=bytes=>{let s='';for(let i=0;i<bytes.length;i+=8192)s+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(s)};
const from64=s=>{if(typeof s!=='string'||s.length>150000000||!/^[A-Za-z0-9+/]*={0,2}$/.test(s))throw Error('Invalid base64 input');const raw=atob(s),out=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)out[i]=raw.charCodeAt(i);return out};
const derive=async(pass,salt)=>{const base=await crypto.subtle.importKey('raw',enc.encode(pass),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:ITERATIONS,hash:'SHA-256'},base,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])};
async function protect(payload,pass){if(!globalThis.isSecureContext||!crypto?.subtle)throw Error('Secure browser unavailable');const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12));const key=await derive(pass,salt),plaintext=enc.encode(JSON.stringify(payload));const data=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:enc.encode('toolbox-documents-encrypted-v1')},key,plaintext));plaintext.fill(0);return {format:'toolbox-documents-encrypted-v1',kdf:'PBKDF2-SHA256',iterations:ITERATIONS,cipher:'AES-256-GCM',salt:bytesTo64(salt),iv:bytesTo64(iv),data:bytesTo64(data)}}
async function unprotect(envelope,pass){if(!globalThis.isSecureContext||!crypto?.subtle)throw Error('Secure browser unavailable');if(envelope?.format!=='toolbox-documents-encrypted-v1'||envelope.kdf!=='PBKDF2-SHA256'||envelope.cipher!=='AES-256-GCM'||envelope.iterations!==ITERATIONS)throw Error('Unsupported backup format');const salt=from64(envelope.salt),iv=from64(envelope.iv);if(salt.length!==16||iv.length!==12)throw Error('Invalid crypto parameters');const key=await derive(pass,salt);const data=from64(envelope.data);const plaintext=new Uint8Array(await crypto.subtle.decrypt({name:'AES-GCM',iv,additionalData:enc.encode('toolbox-documents-encrypted-v1')},key,data));try{return JSON.parse(dec.decode(plaintext))}finally{plaintext.fill(0)}}
const backupPass=()=>document.getElementById('tbBackupPassword')?.value||'';
const backupConfirm=()=>document.getElementById('tbBackupPasswordConfirm')?.value||'';
const clearPasswords=()=>{for(const id of ['tbBackupPassword','tbBackupPasswordConfirm']){const el=document.getElementById(id);if(el)el.value=''}};

const message=(value)=>{const el=document.getElementById('tbBackupStatus');if(el)el.textContent=value;};
const b64=blob=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Unable to read an attachment.'));r.readAsDataURL(blob)});
const toBlob=async(data)=>{if(typeof data!=='string'||!/^data:(image\/(jpeg|png|webp|gif)|application\/pdf);base64,/.test(data))throw Error('Unsupported attachment format.');const response=await fetch(data);return response.blob()};
const download=(payload)=>{const blob=new Blob([JSON.stringify(payload)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='toolbox-documents-encrypted-'+new Date().toISOString().slice(0,10)+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000)};
async function exportAll(button){const pass=backupPass(),verify=backupConfirm();if(pass.length<12){message('Choose a backup passphrase with at least 12 characters.');return}if(pass!==verify){message('Passphrase confirmation does not match.');return}if(!confirm('Create an encrypted backup? Keep the passphrase safe: Toolbox cannot recover the backup if you lose it.'))return;button.disabled=true;message('Encrypting document backup…');try{
 const docs=docRecords(),attachments=[];let total=0;
 for(const doc of docs){for(const side of ['front','back','page','']){const key=doc.id+(side?'::'+side:'');const blob=await photoOperation(key,'read');if(!blob)continue;if(blob.size>MAX_ATTACHMENT)throw Error('An attachment exceeds 15 MB. Reduce its size before exporting.');total+=blob.size;if(total>MAX_FILE)throw Error('Attachments exceed the 60 MB backup limit.');attachments.push({key,type:blob.type||'application/octet-stream',data:await b64(blob)});message('Backing up attachments: '+attachments.length);}}
 const sealed=await protect({format:'toolbox2-full-documents-v1',exportedAt:new Date().toISOString(),documents:docs,attachments},pass);download(sealed);message('Encrypted backup downloaded. Keep its passphrase safe; it cannot be recovered for you.');
 }catch(_err){message('Backup could not be completed. Your existing records have not been intentionally changed. Check storage and try again.')}finally{clearPasswords();button.disabled=false}}
async function importAll(file,button){if(!file)return;button.disabled=true;message('Checking backup file…');try{
 if(file.size>120*1024*1024)throw Error('Backup file exceeds 120 MB.');let payload=JSON.parse(await file.text());if(payload.format==='toolbox-documents-encrypted-v1'){const pass=backupPass();if(!pass){message('Enter the backup passphrase to restore this encrypted file.');return}message('Unlocking encrypted backup…');payload=await unprotect(payload,pass)}else if(payload.format==='toolbox2-full-documents-v1'){if(!confirm('This is an old unencrypted backup. Continue restoring it?'))return}else throw Error('Unsupported backup format');if(payload.format!=='toolbox2-full-documents-v1'||!Array.isArray(payload.documents)||!Array.isArray(payload.attachments))throw Error('Select a full Toolbox Documents backup.');
 if(payload.documents.length>2000||payload.attachments.length>4000)throw Error('Backup contains too many records.');
 const ids=new Set();for(const d of payload.documents){if(!d||typeof d.id!=='string'||!/^doc-[a-zA-Z0-9-]+$/.test(d.id)||ids.has(d.id)||typeof d.title!=='string'||d.title.length>120)throw Error('Backup contains an invalid or duplicate document record.');ids.add(d.id)}
 let size=0;const restored=[];const keys=new Set();for(const a of payload.attachments){if(!a||typeof a.key!=='string'||keys.has(a.key)||typeof a.data!=='string')throw Error('Invalid attachment entry.');const id=a.key.split('::')[0];if(!ids.has(id)||!new RegExp('^'+id+'(?:::front|::back|::page)?$').test(a.key))throw Error('Attachment does not match a document.');keys.add(a.key);const blob=await toBlob(a.data);size+=blob.size;if(blob.size>MAX_ATTACHMENT||size>MAX_FILE)throw Error('Backup attachments exceed size limits.');restored.push({key:a.key,blob});}
 if(!confirm('Import '+payload.documents.length+' document records and '+restored.length+' attachments? Existing records with matching IDs will be replaced. Other records will remain. Export a backup first.')){message('Import cancelled.');return}
 // Write attachments before metadata so partial imports do not create records with missing attachments.
 for(let i=0;i<restored.length;i++){await photoOperation(restored[i].key,'write',restored[i].blob);message('Restoring attachment '+(i+1)+' of '+restored.length+'…')}
 const merged=new Map(docRecords().map(d=>[d.id,d]));for(const d of payload.documents)merged.set(d.id,d);if(!saveDocRecords([...merged.values()]))throw Error('Document metadata could not be saved.');message('Restored '+payload.documents.length+' records and '+restored.length+' attachments.');if(typeof render==='function')render();
 }catch(_err){message('Restore could not be completed. Some attachments may have been written before the failure. Check your records before retrying.')}finally{clearPasswords();button.disabled=false}}
 function install(){const page=document.querySelector('.docs-page');if(!page||page.querySelector('#tbBackupPanel'))return;const panel=document.createElement('section');panel.id='tbBackupPanel';panel.className='tb-backup-panel';panel.innerHTML='<h2>Encrypted Documents Backup</h2><p>Protect a complete offline backup with your own passphrase. Includes document details and saved images/PDFs.</p><div class="tb-backup-fields"><label>Backup passphrase<input id="tbBackupPassword" type="password" autocomplete="new-password" minlength="12" placeholder="At least 12 characters"></label><label>Confirm for new backups<input id="tbBackupPasswordConfirm" type="password" autocomplete="new-password" placeholder="Repeat passphrase for export"></label></div><div class="tb-backup-actions"><button class="btn secondary" type="button" id="tbBackupExport">Download encrypted backup</button><button class="btn secondary" type="button" id="tbBackupImport">Restore backup file</button><input type="file" id="tbBackupFile" accept="application/json,.json" hidden></div><p class="tb-backup-warning">Keep your passphrase: losing it means the encrypted backup cannot be recovered. Existing document storage on this device is still unencrypted and for dummy test files only. Old unencrypted backups can be restored.</p><p id="tbBackupStatus" role="status" aria-live="polite"></p>';
 const old=page.querySelector('#exportDocRecords');if(old)old.insertAdjacentElement('beforebegin',panel);else page.append(panel);
 panel.querySelector('#tbBackupExport').addEventListener('click',e=>exportAll(e.currentTarget));panel.querySelector('#tbBackupImport').addEventListener('click',()=>panel.querySelector('#tbBackupFile').click());panel.querySelector('#tbBackupFile').addEventListener('change',e=>{importAll(e.target.files[0],panel.querySelector('#tbBackupImport'));e.target.value=''});
 }
 const observer=new MutationObserver(()=>{if(document.querySelector('.docs-page')&&!document.getElementById('tbBackupPanel'))install()});observer.observe(document.getElementById('view')||document.body,{childList:true,subtree:true});install();
})();